('Custom T-Shirt Printing', 'custom-t-shirt-printing', 'Apparel', 'High-quality custom t-shirt printing for events, teams, and businesses.', 'Starting at $12/shirt', 'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["1","5","10","25","50","100"],"required":true},{"name":"shirt_color","label":"Shirt Color","type":"text","placeholder":"e.g. Navy, White, Black","required":true},{"name":"print_location","label":"Print Location","type":"select","options":["Front","Back","Front and Back"],"required":true},{"name":"size_breakdown","label":"Size Breakdown","type":"textarea","placeholder":"e.g. S:2, M:5, L:8, XL:3","required":false}]}', true),
('Custom Polo Printing', 'custom-polo-printing', 'Apparel', 'Professional embroidered or printed polos for corporate teams and events.', 'Starting at $18/polo', 'https://images.unsplash.com/photo-1622445275463-aba1ab721103?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["1","5","10","25","50","100"],"required":true},{"name":"polo_color","label":"Polo Color","type":"text","placeholder":"e.g. Navy, White","required":true},{"name":"print_location","label":"Print/Embroidery Location","type":"select","options":["Left Chest","Full Front","Back","Sleeve"],"required":true},{"name":"size_breakdown","label":"Size Breakdown","type":"textarea","placeholder":"e.g. S:2, M:5, L:8","required":false}]}', true),
