('Custom Hats', 'custom-hats', 'Apparel', 'Embroidered or printed caps, beanies, and trucker hats for your brand.', 'Starting at $10/hat', 'https://images.unsplash.com/photo-1588850561407-ed78c282e89b?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["12","24","48","72","144"],"required":true},{"name":"hat_style","label":"Hat Style","type":"select","options":["Structured Cap","Trucker Hat","Beanie","Snapback"],"required":true},{"name":"hat_color","label":"Hat Color","type":"text","placeholder":"e.g. Black, Navy, Khaki","required":true}]}', true),
('Tote Bags', 'tote-bags', 'Apparel', 'Custom printed tote bags for retail, events, and promotional giveaways.', 'Starting at $8/bag', 'https://images.unsplash.com/photo-1591562555315-8019a069fd93?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["25","50","100","250","500"],"required":true},{"name":"bag_color","label":"Bag Color","type":"text","placeholder":"e.g. Natural, Black, Navy","required":true},{"name":"print_sides","label":"Print Sides","type":"select","options":["One Side","Both Sides"],"required":true}]}', true),
('Standard Business Cards', 'business-cards-standard', 'Business Cards', 'Standard business cards from MetroPrint USA (MKT1). Choose stock weight, matte or UV gloss finish, corner style, quantity, and sides.', 'Starting at $29/500', 'https://images.unsplash.com/photo-1586953208448-b95a79798f07?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["50","100","250","500","1000","2500","5000"],"required":true},{"name":"stock","label":"Stock","type":"select","options":["14pt","16pt","18pt"],"required":true},{"name":"finish","label":"Finish","type":"select","options":["Matte","UV Gloss"],"required":true},{"name":"corners","label":"Corners","type":"select","options":["Rectangle","Rounded"],"required":true},{"name":"sides","label":"Sides","type":"select","options":["Single Sided","Double Sided"],"required":true},{"name":"need_design_help","label":"Need Design Help","type":"radio","options":["Yes","No"],"required":true}]}', true),
('Metallic Foil Business Cards', 'business-cards-premium-metallic-foil-raised', 'Business Cards', 'Raised foil business cards with silver or gold custom foil printing. Premium look for high-end branding — MetroPrint USA (MKT1).', 'Starting at $43/100', 'https://images.unsplash.com/photo-1586953208448-b95a79798f07?w=800&h=600&fit=crop', '{"fields":[{"name":"quantity","label":"Quantity","type":"select","options":["25","50","100","250","500","1000","2500"],"required":true},{"name":"size","label":"Size","type":"select","options":["3.5\" x 2\""],"required":true},{"name":"foil_color","label":"Foil Color","type":"select","options":["Gold metallic foil (front)","Silver metallic foil (front)","Gold metallic foil (both sides)","Silver metallic foil (both sides)"],"required":true},{"name":"corners","label":"Corners","type":"select","options":["Rectangle","Rounded"],"required":true},{"name":"sides","label":"Sides","type":"select","options":["Single Sided","Double Sided"],"required":true},{"name":"need_design_help","label":"Need Design Help","type":"radio","options":["Yes","No"],"required":true}]}', true),
